-- Áreas explícitamente acreditadas. No asigna áreas a recursos ni amplía concesiones anteriores.
CREATE TABLE institution_area(id VARCHAR(64) PRIMARY KEY,unit_code VARCHAR(8) NOT NULL,site_id VARCHAR(40) NOT NULL,label VARCHAR(120) NOT NULL,head_mode VARCHAR(24) NOT NULL,valid_from BIGINT NOT NULL,valid_until BIGINT NOT NULL,authority_revision BIGINT NOT NULL,FOREIGN KEY(unit_code,site_id) REFERENCES core_unit_site(unit_code,site_id),FOREIGN KEY(authority_revision) REFERENCES authority_batch(revision),CHECK(valid_until>valid_from),CHECK(head_mode IN ('COORDINACION','DIRECCION')));
CREATE TABLE authority_area_mandate(batch_revision BIGINT NOT NULL,mandate_id VARCHAR(64) NOT NULL,area_id VARCHAR(64) NOT NULL,PRIMARY KEY(batch_revision,mandate_id),FOREIGN KEY(batch_revision,mandate_id) REFERENCES authority_mandate(batch_revision,id),FOREIGN KEY(area_id) REFERENCES institution_area(id));
CREATE TABLE instruction_area(instruction_id VARCHAR(36) PRIMARY KEY,area_id VARCHAR(64) NOT NULL,FOREIGN KEY(instruction_id) REFERENCES access_instruction(id) ON DELETE CASCADE,FOREIGN KEY(area_id) REFERENCES institution_area(id));
CREATE TABLE staff_assignment_area(assignment_id VARCHAR(36) PRIMARY KEY,area_id VARCHAR(64) NOT NULL,FOREIGN KEY(assignment_id) REFERENCES staff_assignment(id) ON DELETE CASCADE,FOREIGN KEY(area_id) REFERENCES institution_area(id));
CREATE TABLE destination_area(destination_id VARCHAR(36) PRIMARY KEY,area_id VARCHAR(64) NOT NULL,FOREIGN KEY(destination_id) REFERENCES core_destination(id),FOREIGN KEY(area_id) REFERENCES institution_area(id));
CREATE TABLE case_area(case_id VARCHAR(36) PRIMARY KEY,area_id VARCHAR(64) NOT NULL,FOREIGN KEY(case_id) REFERENCES core_case(id),FOREIGN KEY(area_id) REFERENCES institution_area(id));
CREATE TABLE case_area_history(seq BIGINT AUTO_INCREMENT PRIMARY KEY,case_id VARCHAR(36) NOT NULL,previous_area VARCHAR(64),area_id VARCHAR(64) NOT NULL,actor_id VARCHAR(64) NOT NULL,at_ms BIGINT NOT NULL,reason_text VARCHAR(1000) NOT NULL,FOREIGN KEY(case_id) REFERENCES core_case(id),FOREIGN KEY(previous_area) REFERENCES institution_area(id),FOREIGN KEY(area_id) REFERENCES institution_area(id),FOREIGN KEY(actor_id) REFERENCES core_actor(id));
CREATE INDEX ix_case_area_area ON case_area(area_id,case_id);
